    ptr = 0
    K = int(input[ptr])
    ptr += 1
    needles = []
    for _ in range(K):
        x1, y1, z1, x2, y2, z2 = map(int, input[ptr:ptr+6])
        ptr += 6
        needles.append(((x1, y1, z1), (x2, y2, z2)))

    # Check for true closed chains
    true_closed = False
    # Build adjacency list for 3D points
    adj = defaultdict(list)
    point_to_needle = {}
    for i, needle in enumerate(needles):
        p1, p2 = needle
        adj[p1].append((p2, i))
        adj[p2].append((p1, i))
        point_to_needle[p1] = point_to_needle.get(p1, []) + [i]
        point_to_needle[p2] = point_to_needle.get(p2, []) + [i]

    # Check for cycles of length >= 3
    visited = set()
    for p in adj:
        if p not in visited:
            stack = [(p, -1, set())]
            while stack:
